// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig, Easing, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadManrope = makeLoadFont('Manrope');

// Module-level font loading for guaranteed availability before frame 0
const { fontFamily: manrope } = loadManrope();



export type LowerThirdNameplateProps = Record<string, any>;

// Deterministic crosshair marker component
const Crosshair: React.FC<{ x: number; y: number; opacity: number; color: string }> = ({ x, y, opacity, color }) => (
  <div style={{
    position: "absolute",
    left: x,
    top: y,
    width: 24,
    height: 24,
    transform: "translate(-50%, -50%)",
    opacity
  }}>
    <div style={{ position: "absolute", left: 11, top: 0, width: 2, height: 24, backgroundColor: color, opacity: 0.6 }} />
    <div style={{ position: "absolute", left: 0, top: 11, width: 24, height: 2, backgroundColor: color, opacity: 0.6 }} />
  </div>
);

const LowerThirdNameplate: React.FC<LowerThirdNameplateProps> = ({
  backgroundColor = "#121420",
  transparentBackground = false,
  durationInSeconds = 6,
  name = "Liam McManus",
  title = "Managing Director",
  primaryColor = "#1A2035", // Corporate Navy
  accentColor = "#F38118",  // Construction Orange
  textColor = "#FFFFFF",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const OUTRO_DURATION = 60;
  const outroStart = Math.max(0, totalFrames - OUTRO_DURATION);
  const isOutro = frame >= outroStart;
  const outroTime = isOutro ? frame - outroStart : 0;

  // Layout proportions optimized for 16:9
  const boxW = width * 0.42;
  const boxH = height * 0.16;
  const leftOffset = width * 0.08;
  const bottomOffset = height * 0.12;
  const leftPad = 48;

  // --- ANIMATION LOGIC (Engineered / Assembled Sequence) ---
  const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
  // Smoother ease for deconstruction
  const easeInOut = Easing.bezier(0.4, 0, 0.2, 1);

  // Entry Interpolations
  const introPanelH = interpolate(frame, [15, 40], [0, boxH], { easing: easeOut, extrapolateRight: "clamp" });
  const introPillarX = interpolate(frame, [25, 45], [-40, 0], { easing: easeOut, extrapolateRight: "clamp" });
  const introPillarO = interpolate(frame, [25, 35], [0, 1], { easing: easeOut, extrapolateRight: "clamp" });
  const introNameY = interpolate(frame, [35, 55], [60, 0], { easing: easeOut, extrapolateRight: "clamp" });
  const introTitleY = interpolate(frame, [40, 60], [40, 0], { easing: easeOut, extrapolateRight: "clamp" });
  const introTextO = interpolate(frame, [35, 50], [0, 1], { easing: easeOut, extrapolateRight: "clamp" });
  const introCrosshairO = interpolate(frame, [5, 20], [0, 1], { easing: easeOut, extrapolateRight: "clamp" });

  // Outro Interpolations (Smoother, overlapping transitions)
  const oTextO = interpolate(outroTime, [0, 20], [1, 0], { easing: easeInOut, extrapolateRight: "clamp" });
  const oTitleY = interpolate(outroTime, [0, 30], [0, 40], { easing: easeInOut, extrapolateRight: "clamp" });
  const oNameY = interpolate(outroTime, [5, 35], [0, 60], { easing: easeInOut, extrapolateRight: "clamp" });
  const oPanelH = interpolate(outroTime, [10, 50], [boxH, 0], { easing: easeInOut, extrapolateRight: "clamp" });
  const oPillarX = interpolate(outroTime, [15, 55], [0, -40], { easing: easeInOut, extrapolateRight: "clamp" });
  const oPillarO = interpolate(outroTime, [25, 60], [1, 0], { easing: easeInOut, extrapolateRight: "clamp" });
  const oCrosshairO = interpolate(outroTime, [30, 60], [1, 0], { easing: easeInOut, extrapolateRight: "clamp" });

  // Active States
  const currentPanelH = isOutro ? oPanelH : introPanelH;
  const currentPillarX = isOutro ? oPillarX : introPillarX;
  const currentPillarO = isOutro ? oPillarO : introPillarO;
  const currentNameY = isOutro ? oNameY : introNameY;
  const currentTitleY = isOutro ? oTitleY : introTitleY;
  const currentTextO = isOutro ? oTextO : introTextO;
  const currentCrosshairO = isOutro ? oCrosshairO : introCrosshairO;

  // Subtle continuous motion
  const containerScale = interpolate(frame, [0, totalFrames], [1, 1.02]);
  const bgPan = interpolate(frame, [0, totalFrames], [0, -50]);

  // Generate deterministic "construction dust" particles
  const particles = useMemo(() => {
    return Array.from({ length: 40 }).map((_, i) => ({
      id: i,
      left: random(`left-${i}`) * 100 + "%",
      top: random(`top-${i}`) * 120, // percentage initially
      size: random(`size-${i}`) * 3 + 1,
      speed: random(`speed-${i}`) * 1.2 + 0.3,
      opacity: random(`op-${i}`) * 0.25 + 0.05,
      wobbleSpeed: random(`ws-${i}`) * 0.03 + 0.01,
      wobbleAmount: random(`wa-${i}`) * 15 + 5
    }));
  }, []);

  const bgColorValue = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColorValue, overflow: "hidden", fontFamily: manrope }}>
      
      {/* Studio Background Elements (Hidden if transparent) */}
      {!transparentBackground && (
        <>
          {/* Subtle Blueprint Grid */}
          <div style={{ position: "absolute", inset: 0, opacity: 0.15, transform: `translate(${bgPan}px, ${bgPan}px)` }}>
            <svg width="200%" height="200%">
              <defs>
                <pattern id="blueprintGrid" width="60" height="60" patternUnits="userSpaceOnUse">
                  <path d="M 60 0 L 0 0 0 60" fill="none" stroke="#FFFFFF" strokeWidth="1" opacity="0.3" />
                  <path d="M 30 0 L 30 60 M 0 30 L 60 30" fill="none" stroke="#FFFFFF" strokeWidth="0.5" opacity="0.1" />
                </pattern>
              </defs>
              <rect width="100%" height="100%" fill="url(#blueprintGrid)" />
            </svg>
          </div>

          {/* Soft Studio Lighting */}
          <div style={{
            position: "absolute", inset: 0,
            background: `radial-gradient(circle at 70% 30%, ${accentColor}10 0%, transparent 50%), radial-gradient(circle at 20% 80%, ${primaryColor}60 0%, transparent 60%)`,
            pointerEvents: "none"
          }} />

          {/* Construction Dust Particles */}
          <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
            {particles.map(p => {
              const yOffset = frame * p.speed;
              const xOffset = Math.sin(frame * p.wobbleSpeed) * p.wobbleAmount;
              return (
                <div key={p.id} style={{
                  position: "absolute",
                  left: p.left,
                  top: `${p.top}%`,
                  width: p.size, height: p.size,
                  backgroundColor: accentColor,
                  opacity: p.opacity,
                  borderRadius: "50%",
                  transform: `translate(${xOffset}px, -${yOffset}px)`,
                  filter: `blur(${p.size * 0.4}px)`,
                  mixBlendMode: "screen"
                }} />
              );
            })}
          </div>
        </>
      )}

      {/* Main Lower Third Container */}
      <div style={{
        position: "absolute",
        left: leftOffset,
        bottom: bottomOffset,
        width: boxW,
        height: boxH,
        transform: `scale(${containerScale})`,
        transformOrigin: "bottom left"
      }}>
        
        {/* Crosshair Markers */}
        <Crosshair x={0} y={0} opacity={currentCrosshairO} color={accentColor} />
        <Crosshair x={boxW} y={0} opacity={currentCrosshairO} color={accentColor} />
        <Crosshair x={boxW} y={boxH} opacity={currentCrosshairO} color={accentColor} />

        {/* Main Navy Panel */}
        <div style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: boxW,
          height: currentPanelH,
          backgroundColor: primaryColor,
          overflow: "hidden",
          boxShadow: currentPanelH > 10 ? "10px 20px 40px rgba(0,0,0,0.3)" : "none"
        }}>
          {/* Inner Panel Pattern */}
          <div style={{ position: "absolute", inset: 0, opacity: 0.05 }}>
            <svg width="100%" height="100%">
              <defs>
                <pattern id="panelPattern" width="20" height="20" patternUnits="userSpaceOnUse">
                  <path d="M 20 0 L 0 0 0 20" fill="none" stroke="#FFFFFF" strokeWidth="1" />
                </pattern>
              </defs>
              <rect width="100%" height="100%" fill="url(#panelPattern)" />
            </svg>
          </div>

          {/* Text Container */}
          <div style={{
            position: "absolute",
            left: leftPad,
            top: 0,
            bottom: 0,
            width: boxW - leftPad - 20,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center"
          }}>
            {/* Name */}
            <div style={{ overflow: "hidden", paddingBottom: 4 }}>
              <h1 style={{
                margin: 0,
                fontSize: boxH * 0.38,
                fontWeight: 800,
                color: textColor,
                letterSpacing: "-0.02em",
                transform: `translateY(${currentNameY}px)`,
                opacity: currentTextO,
                lineHeight: 1.1
              }}>
                {name}
              </h1>
            </div>
            {/* Title */}
            <div style={{ overflow: "hidden", paddingTop: 2 }}>
              <h2 style={{
                margin: 0,
                fontSize: boxH * 0.16,
                fontWeight: 500,
                color: accentColor,
                letterSpacing: "0.15em",
                textTransform: "uppercase",
                transform: `translateY(${currentTitleY}px)`,
                opacity: currentTextO,
                lineHeight: 1.2
              }}>
                {title}
              </h2>
            </div>
          </div>
        </div>

        {/* Orange Accent Pillar (Left) */}
        <div style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: 16,
          height: boxH,
          backgroundColor: accentColor,
          transform: `translateX(${currentPillarX}px)`,
          opacity: currentPillarO,
          boxShadow: "2px 0 10px rgba(0,0,0,0.3)",
          zIndex: 10
        }} />

      </div>
    </AbsoluteFill>
  );
};

export default LowerThirdNameplate;